function h($s){ return htmlspecialchars((string)($s ?? ''), ENT_QUOTES, 'UTF-8'); }
function norm($p){ return str_replace('\\','/',(string)$p); }
function safe_path($path,$root){
  $rootReal = norm(realpath($root) ?: $root);
  $real = realpath($path);
  if(!$real) return $rootReal;
  $real = norm($real);
  return strpos($real,$rootReal)===0 ? $real : $rootReal;
}
function is_inside($path,$root){
  $rootReal = norm(realpath($root) ?: $root);
  $real = realpath($path);
  if(!$real) return false;
  return strpos(norm($real),$rootReal)===0;
}
function safe_name($name){ return str_replace(["\0",'/',"\\"],'',basename((string)$name)); }
function allowed_ext($file,$allowed){
  $base=basename($file);
  if($base==='.htaccess' && in_array('htaccess',$allowed,true)) return true;
  if(strpos($base,'.')===0 && $base!=='.htaccess') return false;
  $ext=strtolower(pathinfo($file,PATHINFO_EXTENSION));
  return in_array($ext,$allowed,true);
}
function sizef($b){ $b=(int)$b; if($b>=1073741824)return round($b/1073741824,2).' GB'; if($b>=1048576)return round($b/1048576,2).' MB'; if($b>=1024)return round($b/1024,1).' KB'; return $b.' B'; }
function pub_url($file){
  $doc = norm(realpath($_SERVER['DOCUMENT_ROOT']) ?: ''); $real = realpath($file);
  if(!$doc || !$real) return '';
  $real=norm($real); if(strpos($real,$doc)!==0) return '';
  $rel=str_replace('%2F','/',rawurlencode(substr($real,strlen($doc))));
  $rel=preg_replace('#%2F#i','/',$rel);
  $scheme=(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off')?'https':'http';
  return $scheme.'://'.$_SERVER['HTTP_HOST'].$rel;
}
function breadcrumb($path,$root){
  $path=norm($path); $root=norm($root); $rel=trim(str_replace($root,'',$path),'/');
  $html='<a href="?p='.urlencode($root).'">ROOT</a>'; $build=$root;
  if($rel){ foreach(explode('/',$rel) as $part){ $build.='/'.$part; $html.=' <span>/</span> <a href="?p='.urlencode($build).'">'.h($part).'</a>'; } }
  return $html;
}
function rrmdir($dir,$root){
  if(!is_dir($dir) || !is_inside($dir,$root)) return false;
  $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);
  foreach($it as $f){ $f->isDir()?@rmdir($f->getPathname()):@unlink($f->getPathname()); }
  return @rmdir($dir);
}
function zip_paths($paths,$dest,$root){
  if(!class_exists('ZipArchive')) return [false,'ZipArchive tidak aktif di hosting.'];
  $zip=new ZipArchive(); if($zip->open($dest,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true) return [false,'Gagal membuat ZIP.'];
  foreach($paths as $source){
    if(!is_inside($source,$root)) continue;
    $source=norm(realpath($source)); $base=basename($source);
    if(is_dir($source)){
      $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
      foreach($it as $file){ $fp=norm($file->getRealPath()); $local=$base.'/'.trim(str_replace($source,'',$fp),'/'); $file->isDir()?$zip->addEmptyDir($local):$zip->addFile($fp,$local); }
    } elseif(is_file($source)) $zip->addFile($source,$base);
  }
  $zip->close(); return [true,'ZIP berhasil dibuat.'];
}
function parse_terminal_line($line){
  $line=trim($line); $out='';
  if(preg_match('/(?:curl|wget)\s+.*?(?:-o|-O)\s+[\"\']?([^\s\"\']+)/i',$line,$m)) $out=basename($m[1]);
  if(preg_match_all('/https?:\/\/[^\s\"\']+/i',$line,$m) && !empty($m[0])) $url=end($m[0]); else $url=$line;
  if(!$out){ $path=parse_url($url,PHP_URL_PATH); $out=basename($path ?: 'remote-file.txt'); }
  return [$url,safe_name($out)];
}
function remote_download($url,$target){
  if(!filter_var($url,FILTER_VALIDATE_URL)) return [false,'URL/curl/wget tidak valid.'];
  $sch=strtolower(parse_url($url,PHP_URL_SCHEME) ?: ''); if(!in_array($sch,['http','https'],true)) return [false,'Hanya HTTP/HTTPS.'];
  if(function_exists('curl_init')){ $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>30,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_USERAGENT=>'ConquerorSafeManager/5']); $data=curl_exec($ch); $err=curl_error($ch); $code=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); if($data===false || $code>=400) return [false,'Fetch gagal '.$err.' HTTP '.$code]; }
  else { $ctx=stream_context_create(['http'=>['timeout'=>30,'user_agent'=>'ConquerorSafeManager/5']]); $data=@file_get_contents($url,false,$ctx); if($data===false) return [false,'Fetch gagal.']; }
  if(strlen($data)>25*1024*1024) return [false,'File terlalu besar, max 25MB.'];
  return file_put_contents($target,$data)!==false ? [true,'Terminal fetch sukses: '.basename($target)] : [false,'Gagal simpan file. Cek permission.'];
}
