  $res=[]; $count=0; $root=norm(realpath($root)?:$root);
  try{ $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS)); foreach($it as $file){ if($count++>=$limit) break; if(!$file->isFile()) continue; $path=norm($file->getPathname()); if(strpos($path,$root)!==0) continue; $base=basename($path); $ext=strtolower(pathinfo($path,PATHINFO_EXTENSION)); if(!in_array($ext,['php','phtml','phar','inc','txt','js','html','htaccess'],true)&&$base!=='.htaccess') continue; if(@filesize($path)>2*1024*1024) continue; $c=@file_get_contents($path,false,null,0,280000); if($c===false) continue; $hits=[]; foreach($patterns as $rx=>$label){ if(@preg_match('/'.$rx.'/i',$c)) $hits[]=$label; } if(preg_match('/(shell|backdoor|wso|c99|r57|b374k|cmd|mailer|leaf|xleet|up\.php)/i',$base)) $hits[]='suspicious filename'; if($hits) $res[]=['file'=>$path,'hits'=>array_values(array_unique($hits)),'size'=>@filesize($path),'perm'=>substr(sprintf('%o',@fileperms($path)),-4),'dir'=>dirname($path),'url'=>pub_url($path),'dirurl'=>pub_url(dirname($path).'/index.html') ?: pub_url(dirname($path))]; } }
  catch(Exception $e){ $res[]=['file'=>'SCAN_ERROR','hits'=>[$e->getMessage()],'size'=>0,'perm'=>'-','dir'=>'','url'=>'','dirurl'=>'']; }
  return $res;
}

