in-top:14px;background:rgba(0,0,0,.28);border-radius:12px;overflow:hidden}th,td{padding:10px;border-bottom:1px solid rgba(255,255,255,.08);text-align:left;vertical-align:middle;font-size:13px}th{color:#ffd36e;background:rgba(255,190,62,.06)}td a{color:#ffd36e;text-decoration:none;font-weight:bold}.checks{width:18px;height:18px}.actions{display:flex;gap:6px;flex-wrap:wrap}.small{font-size:12px;color:#aaa}.smallform{display:flex;gap:5px}.smallform input{width:86px}.scanbox{max-height:460px;overflow:auto}.scanitem{padding:10px;margin-top:10px;border:1px solid rgba(255,87,87,.25);border-radius:12px;background:rgba(255,0,0,.05)}.scanfile{font-size:12px;word-break:break-all;color:#ffd36e;line-height:1.5}.scanhit{font-size:12px;color:#ffadad;margin:6px 0}.editor textarea,.viewer textarea{min-height:430px;font-family:monospace;font-size:13px}.viewer img{max-width:100%;border-radius:12px;border:1px solid rgba(255,190,62,.3)}@media(max-width:1050px){.app{grid-template-columns:1fr}.side{position:relative}.side img{max-width:220px}.menu{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.menu a{margin:0}}@media(max-width:700px){.main{padding:10px}.topbar{height:auto;gap:8px;flex-wrap:wrap;padding:10px}.menu{grid-template-columns:1fr}th:nth-child(4),td:nth-child(4),th:nth-child(5),td:nth-child(5){display:none}.smallform{flex-direction:column}.smallform input{width:100%}}
</style></head><body><div class="app"><aside class="side"><img src="<?=h($LOGO_URL)?>" alt="CONQUEROR"><div class="user"><b><?=h($userName)?></b><br><span class="small">Role: <?=h($userRole)?> • <span class="online">Online</span></span></div><nav class="menu"><a href="#dash">⌂ Dashboard</a><a href="#scanner">🛡 Scanner Module</a><a href="#terminal">▻ Terminal Module</a><a class="active" href="#filemanager">📁 File Manager</a><a href="#settings">⚙ Settings</a><a href="?logout=1">↪ Logout</a></nav><div class="small" style="position:fixed;bottom:18px;left:18px">♛ CONQUEROR PANEL v5<br>© Safe defensive build</div></aside><main class="main"><div class="topbar"><div>WELCOME, <b style="color:#ffd36e"><?=h($userName)?></b> &nbsp; <span class="online">● Online</span></div><div><?=date('H:i:s')?> &nbsp; | &nbsp; <?=date('d M Y')?></div></div><section class="panel" id="filemanager"><div class="title"><h2>📁 FILE MANAGER</h2><div class="actions"><a class="btn btn-dark" href="?p=<?=urlencode($ROOT)?>">Root</a><a class="btn btn-red" href="?logout=1">Logout</a></div></div><div class="path">CURRENT PATH: <?=breadcrumb($path,$ROOT)?></div><?php if($msg):?><div class="msg <?=h($msgType)?>"><?=h($msg)?></div><?php endif;?><div class="grid"><div class="card"><b>⬆️ UPLOAD</b><br><br><form method="post" enctype="multipart/form-data" id="uploadForm"><div class="drop" id="dropzone">DRAG & DROP FILES HERE<br><small>or click to browse</small><input type="file" name="file[]" id="fileInput" multiple style="display:none"></div><br><button name="upload">UPLOAD</button></form></div><div class="card"><b>▻ TERMINAL ( CURL / WGET )</b><br><br><form method="post"><input name="terminal_line" placeholder="curl https://domain.com/file.zip -o file.zip  /  wget https://domain.com/file.zip" required><br><br><button name="terminal_fetch">EXECUTE FETCH</button></form><p class="small">1 kolom saja. Sistem ambil URL dari command, bukan menjalankan shell. Manusia memang suka tombol bahaya, jadi ini versi yang masih waras.</p></div><div class="card"><b>➕ NEW FILE</b><br><br><form method="post"><input name="file_name" placeholder="index.html"><br><br><button name="create_file">NEW FILE</button></form></div><div class="card"><b>📁 NEW FOLDER</b><br><br><form method="post"><input name="folder_name" placeholder="assets"><br><br><button name="create_folder">NEW FOLDER</button></form></div><div class="card"><b>🗜 ZIP BACKUP</b><br><br><form method="post"><button name="zip_backup">ZIP CURRENT FOLDER</button></form></div></div><form method="post" id="bulkForm"><div class="actions" style="margin-top:14px"><label class="btn btn-dark" style="color:#ffd36e"><input type="checkbox" id="checkAll" style="width:auto"> SELECT ALL</label><button class="btn-red" name="bulk_delete" onclick="return confirm('Hapus semua item terpilih?')">🗑 DELETE SELECTED</button><button name="bulk_zip">🗜 ZIP SELECTED</button></div><table><thead><tr><th></th><th>NAME</th><th>SIZE</th><th>TYPE</th><th>MODIFIED</th><th>PERMISSIONS</th><th>ACTIONS</th></tr></thead><tbody><?php if($path!==$ROOT):?><tr><td></td><td colspan="6"><a href="?p=<?=urlencode(dirname($path))?>">⬆️ Parent Folder</a></td></tr><?php endif;?><?php if($items): foreach($items as $i): if($i==='.'||$i==='..')continue; $fp=$path.'/'.$i; $isDir=is_dir($fp); $perm=substr(sprintf('%o',@fileperms($fp)),-4);?><tr><td><input class="checks itemCheck" type="checkbox" name="selected[]" value="<?=h($i)?>"></td><td><?= $isDir?'📁':'📄' ?> <?php if($isDir):?><a href="?p=<?=urlencode($fp)?>"><?=h($i)?></a><?php else:?><?=h($i)?><?php endif;?></td><td><?=$isDir?'-':h(sizef(@filesize($fp)))?></td><td><?=$isDir?'Folder':h(strtoupper(pathinfo($fp,PATHINFO_EXTENSION)?:'FILE'))?></td><td><?=h(date('d M Y H:i',@filemtime($fp)))?></td><td><?=h($perm)?></td><td><div class="actions"><?php if(!$isDir):?><a class="btn btn-blue" href="?p=<?=urlencode($path)?>&open=<?=urlencode($i)?>">👁</a><?php endif;?><?php if(!$isDir && allowed_ext($fp,$ALLOWED_EDIT)):?><a class="btn" href="?p=<?=urlencode($path)?>&edit=<?=urlencode($i)?>" target="_blank">✎</a><?php endif;?><a class="btn btn-red" href="?p=<?=urlencode($path)?>&del=<?=urlencode($i)?>" onclick="return confirm('Hapus item ini?')">🗑</a></div><form class="smallform" method="post" style="margin-top:6px"><input type="hidden" name="old_name" value="<?=h($i)?>"><input name="new_name" placeholder="rename"><button name="rename">R</button></form><form class="smallform" method="post" style="margin-top:6px"><input type="hidden" name="chmod_file" value="<?=h($i)?>"><input name="chmod_val" value="<?=h($perm)?>" maxlength="4"><button name="chmod">C</button></form></td></tr><?php endforeach; endif;?></tbody></table></form><?php if(isset($_GET['open'])): $open=safe_name($_GET['open']); $file=$path.'/'.$open; if(is_file($file)): $ext=strtolower(pathinfo($file,PATHINFO_EXTENSION));?><div class="card viewer" style="margin-top:16px"><h2>👁️ Open: <?=h($open)?></h2><?php if(in_array($ext,['png','jpg','jpeg','webp','gif','svg','ico'],true)):?><img src="<?=h(pub_url($file))?>"><p><a class="btn btn-blue" href="<?=h(pub_url($file))?>" target="_blank">Open Public URL</a></p><?php else:?><textarea readonly><?=h(@file_get_contents($file))?></textarea><?php endif;?></div><?php endif; endif;?><?php $editFile=''; $editTitle=''; $editAbs=''; if(isset($_GET['edit_abs'])){ $editFile=safe_path(base64_decode($_GET['edit_abs']),$ROOT); $editTitle=str_replace(norm($ROOT),'ROOT',norm($editFile)); $editAbs=base64_encode($editFile); } elseif(isset($_GET['edit'])){ $editFile=$path.'/'.safe_name($_GET['edit']); $editTitle=basename($editFile); } if($editFile && is_file($editFile) && allowed_ext($editFile,$ALLOWED_EDIT)):?><div class="card editor" style="margin-top:16px"><h2>✏️ Edit: <?=h($editTitle)?></h2><form method="post"><input type="hidden" name="name" value="<?=h(basename($editFile))?>"><input type="hidden" name="edit_abs" value="<?=h($editAbs)?>"><textarea name="content"><?=h(@file_get_contents($editFile))?></textarea><br><br><button name="save">SAVE FILE</button></form></div><?php endif;?></section><section class="panel" id="scanner" style="margin-top:16px"><div class="title"><h2>🛡 SCANNER MODULE</h2><form method="post"><button name="scan_backdoor">SCAN DOMAIN</button></form></div><p class="small">Hasil scanner sekarang punya tombol Preview folder, Delete, dan Edit tab baru. Akhirnya tombolnya bukan hiasan museum digital.</p><?php if(!empty($scanResults)):?><div class="scanbox"><?php foreach($scanResults as $r): $enc=base64_encode($r['file']); $dir=dirname($r['file']); $dirUrl=pub_url($dir);?><div class="scanitem"><div class="scanfile"><?=h(str_replace(norm($ROOT),'ROOT',norm($r['file'])))?></div><div class="scanhit">Deteksi: <?=h(implode(', ',$r['hits']))?><br>Size: <?=h(sizef($r['size']))?> | Perm: <?=h($r['perm'])?></div><div class="actions"><a class="btn btn-blue" href="<?=h($dirUrl ?: '#')?>" target="_blank">👁 PREVIEW FOLDER</a><a class="btn" href="?edit_abs=<?=urlencode($enc)?>" target="_blank">✎ EDIT</a><a class="btn btn-red" href="?scan_del=<?=urlencode($enc)?>" onclick="return confirm('Hapus file mencurigakan ini?')">🗑 DELETE</a></div></div><?php endforeach;?></div><?php elseif(isset($_POST['scan_backdoor'])):?><p style="color:#9dffbd">Tidak ada pola mencurigakan dari scanner basic.</p><?php endif;?></section></main></div><script>
const dz=document.getElementById('dropzone'),fi=document.getElementById('fileInput'); if(dz&&fi){dz.onclick=()=>fi.click(); dz.ondragover=e=>{e.preventDefault();dz.classList.add('dragover')}; dz.ondragleave=()=>dz.classList.remove('dragover'); dz.ondrop=e=>{e.preventDefault();dz.classList.remove('dragover');fi.files=e.dataTransfer.files;dz.innerHTML=e.dataTransfer.files.length+' file siap upload'}; fi.onchange=()=>dz.innerHTML=fi.files.length+' file siap upload'} const all=document.getElementById('checkAll'); if(all){all.onchange=()=>document.querySelectorAll('.itemCheck').forEach(c=>c.checked=all.checked)}
</script></body></html>
